/* Shared by the EE program and the host reference. */
#ifndef DEMO_H
#define DEMO_H

#include <stdint.h>

#include "poly.h" /* generated by vuk: VUK_D and the VU data memory layout */

#define D VUK_D

/* Work: N_TOTAL quadwords (4 floats each).

   demo_all works in rounds. The EE writes one VU0 batch (through COP2) and
   starts VU0; while VU0 computes, the EE reads back VU1's previous batch,
   sends VU1 the next one by DMA and runs the FPU on a few quadwords; then it
   reads VU0's results. The EE is the limit, not the VUs. Measured on the PS2,
   per quadword: a VU computes it in 25 cycles; the EE spends 17 writing and
   8.5 reading VU0's, 32 reading VU1's, and 174 on the FPU. So VU1 gets what
   the EE serves while VU0 computes (180 * 32 ~ 240 * 25), the FPU a token
   share: about 28 cycles per quadword in all, against 49 for VU0 alone. */
#define N_VU1     960                  /* VU1 batch alone; VU1 data memory: 1024 quadwords */
#define N_VU0     240                  /* VU0 batch; VU0 data memory: 256 quadwords */
#define ROUNDS    6
#define N_VU1_ROUND 180                /* VU1 quadwords per round */
#define N_FPU_ROUND 4                  /* FPU quadwords per round */
#define N_ROUND   (N_VU0 + N_VU1_ROUND + N_FPU_ROUND)
#define N_TOTAL   (ROUNDS * N_ROUND)

#if VUK_POLY_X + N_VU1 > 1024 || VUK_POLY_X + N_VU0 > 256
#error "batch does not fit in VU data memory"
#endif

/* Exact inputs: x in {-1, -0.5, 0, 0.5, 1}, integer coefficients in -4..4.
   With D <= 16 every intermediate of Horner's method has at most 24
   significant bits, so the PS2's non-IEEE rounding cannot change a result. */
#if D > 16
#error "D > 16 breaks the exact-result guarantee"
#endif
#if D % 4
#error "the EE code evaluates 4 degrees per step: D must be a multiple of 4"
#endif

static inline uint32_t demo_rand(uint32_t *s) {
  *s = *s * 1664525u + 1013904223u;
  return *s >> 16;
}

static inline void demo_init(float *x, float *c) {
  static const float xs[5] = {-1.0f, -0.5f, 0.0f, 0.5f, 1.0f};
  uint32_t s = 12345;
  for (int k = 0; k <= D; k++)
    c[k] = (float)((int)(demo_rand(&s) % 9) - 4);
  for (int i = 0; i < 4 * N_TOTAL; i++)
    x[i] = xs[demo_rand(&s) % 5];
}

/* Sum of the result bit patterns, with -0 counted as +0 (the units may
   differ in the sign of a zero result). */
static inline uint32_t demo_checksum(const float *y, int n) {
  uint32_t sum = 0;
  for (int i = 0; i < n; i++) {
    union { float f; uint32_t u; } v = {y[i]};
    uint32_t u = v.u == 0x80000000u ? 0u : v.u;
    /* exact results have empty low mantissa bits: mix the high bits down */
    sum = (sum ^ u ^ (u >> 13) ^ (u >> 23)) * 16777619u;
  }
  return sum;
}

#endif
